SELECT count(*) FROM public.title title
  LEFT JOIN (SELECT key1, 1 AS hit FROM (SELECT cc.movie_id AS key1 FROM public.complete_cast cc, public.comp_cast_type cct1 WHERE cct1.id = cc.status_id AND cct1.kind = 'complete+verified' INTERSECT SELECT mc.movie_id AS key1 FROM public.company_name cn, public.company_type ct, public.movie_companies mc WHERE cn.id = mc.company_id AND ct.id = mc.company_type_id AND cn.country_code = '[us]' INTERSECT SELECT mi.movie_id AS key1 FROM public.info_type it1, public.movie_info mi WHERE it1.id = mi.info_type_id AND it1.info = 'release dates' INTERSECT SELECT mk.movie_id AS key1 FROM public.keyword k, public.movie_keyword mk WHERE k.id = mk.keyword_id) x) b1 ON title.id = b1.key1
  LEFT JOIN (SELECT DISTINCT key1, 1 AS hit FROM (SELECT kt.id AS key1 FROM public.kind_type kt WHERE (kt.kind = 'movie' OR kt.kind = 'tv movie' OR kt.kind = 'video movie' OR kt.kind = 'video game')) x) b2 ON title.kind_id = b2.key1
WHERE (b2.hit IS NOT NULL AND b1.hit IS NOT NULL AND COALESCE(title.production_year > 1990, false));
